// Запросы в Travelpayouts под второе плечо: Казахстан -> Вьетнам, октябрь 2026.
// Вылет из Алматы или Астаны (решение 18.08.2026): оттуда рейсов кратно больше,
// чем из Актау, и второе плечо покупается как отдельный билет.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами, не аэропортовыми. Проверено 18.08.2026:
// спрашиваешь CXR — приходит NHA (Нячанг), GYD — приходит BAK, а на DXB вдобавок
// прилетают рейсы через SHJ (Шарджа). В списках держим то, что API ОТДАЁТ.
const MONTH = '2026-10';
const ORIGINS = ['ALA', 'NQZ'];          // откуда реально летим во Вьетнам
const VN = ['SGN', 'NHA'];               // Хошимин и Нячанг
const HUBS = ['DXB', 'SHJ', 'IST', 'TAS', 'BKK', 'KUL', 'URC'];
const FEEDER = 'SCO';                    // Актау -> Алматы/Астана, подвоз к плечу

const out = [];
// 1. сквозные: то, что рынок продаёт одним билетом
for (const o of ORIGINS) for (const d of VN) out.push({ json: { origin: o, destination: d, leg: 'through', month: MONTH } });
// 2. подвоз из Актау — чтобы считать полную стоимость, а не только второе плечо
for (const o of ORIGINS) out.push({ json: { origin: FEEDER, destination: o, leg: 'feeder', month: MONTH } });
// 3. половинки связок через хаб
for (const o of ORIGINS) for (const h of HUBS) out.push({ json: { origin: o, destination: h, leg: 'legA', month: MONTH } });
for (const h of HUBS) for (const d of VN) out.push({ json: { origin: h, destination: d, leg: 'legB', month: MONTH } });
return out;

// Архив цен Travelpayouts по второму плечу — «дёшево сейчас или нет».
// Только сквозные маршруты: медиану по связке из двух билетов никто не считает,
// сравнивать будет не с чем.
// Эндпоинт один — /v2/prices/latest; /v1/prices/calendar выкинут (отдаёт цены
// туда-обратно и игнорирует запрошенный месяц), подробности в плече 1.
const YEAR_START = '2026-01-01';
const ROUTES = [['ALA', 'SGN'], ['ALA', 'NHA'], ['NQZ', 'SGN'], ['NQZ', 'NHA']];

const out = [];
for (const [origin, destination] of ROUTES) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Плечо 2: Казахстан -> Вьетнам, октябрь 2026 =====
// Вылет из Алматы (ALA) или Астаны (NQZ) — из Актау рейсов во Вьетнам почти нет,
// а из этих двух городов рынок нормальный. Считаем три вещи на каждый маршрут:
//   through — один билет, как продаёт рынок;
//   self    — два отдельных билета через хаб (часто дешевле, но риск стыковки на нас);
//   total   — то же плюс подвоз Актау -> Алматы/Астана, чтобы видеть полную стоимость.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами (CXR->NHA, GYD->BAK, на DXB прилетает
// ещё и SHJ). В списках держим то, что API ОТДАЁТ, иначе фильтр съедает всю выдачу.
const SUF = ''; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-10-01', max: '2026-10-31' };
const ORIGINS = ['ALA', 'NQZ'];
const VN = ['SGN', 'NHA'];
const HUBS = ['DXB', 'SHJ', 'IST', 'TAS', 'BKK', 'KUL', 'URC'];
const FEEDER = 'SCO';
const ASSUMED_LEG_H = 4;
const MIN_LAYOVER_H = 6;    // международная стыковка: багаж, паспортный контроль
const MAX_LAYOVER_H = 36;   // дольше — это уже вторая поездка, а не стыковка

// Расширено по факту выдачи 18.08.2026. Коды FS, C6, HH, 3L не расшифрованы —
// покажутся как есть, это честнее выдуманного названия.
const AIRLINES = {
  FZ: 'flydubai', EK: 'Emirates', TK: 'Turkish', VF: 'AJet', HY: 'Uzbekistan',
  KC: 'Air Astana', DV: 'SCAT', J2: 'AZAL', VJ: 'VietJet', VN: 'Vietnam Airlines',
  QH: 'Bamboo', CZ: 'China Southern', SU: 'Аэрофлот', U6: 'Уральские', QR: 'Qatar',
  G9: 'Air Arabia', IX: 'Air India Express', AI: 'Air India', GF: 'Gulf Air',
  PC: 'Pegasus', D7: 'AirAsia X', XJ: 'Thai AirAsia X', CA: 'Air China',
  MU: 'China Eastern', XY: 'flynas', KU: 'Kuwait Airways', WY: 'Oman Air',
  '6E': 'IndiGo', OD: 'Batik Air', ZE: 'Eastar Jet', IQ: 'Qazaq Air', TG: 'Thai Airways',
  MH: 'Malaysia Airlines', AK: 'AirAsia', SQ: 'Singapore', BI: 'Royal Brunei',
};
const CITY = {
  SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', SGN: 'Хошимин', NHA: 'Нячанг',
  DXB: 'Дубай', SHJ: 'Шарджа', IST: 'Стамбул', TAS: 'Ташкент',
  BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи',
};
const name = c => CITY[c] || c;

const inWindow = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const hours = ms => ms / 3600000;

// --- 1. Разбор ответов Travelpayouts -----------------------------------------
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inWindow(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: t.origin, to: t.destination, date, depart_at, price,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        link: t.link || null,
      });
    }
  }
} catch (e) {}

const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
const minByDate = (from, to) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  return Object.values(byDate);
};
const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

// --- 2. Связки через хаб ------------------------------------------------------
// Стыковку проверяем по времени вылета и прилёта, а не по датам: иначе получаются
// схемы, где второй рейс улетает раньше, чем приземлился первый.
const combos = [];
for (const origin of ORIGINS) {
  for (const hub of HUBS) {
    const legA = minByDate(origin, hub);
    if (!legA.length) continue;
    for (const dst of VN) {
      const legB = minByDate(hub, dst);
      if (!legB.length) continue;
      for (const a of legA) {
        const arr = arrivalOf(a);
        if (!arr) continue;
        for (const b of legB) {
          const dep = new Date(b.depart_at);
          if (isNaN(dep)) continue;
          const gap = hours(dep - arr);
          if (gap < MIN_LAYOVER_H || gap > MAX_LAYOVER_H) continue;
          combos.push({
            origin, to: dst, hub, hub_city: name(hub),
            price: a.price + b.price, date: a.date,
            layover_h: Math.round(gap * 10) / 10,
            legA: a, legB: b, kind: 'self', src: 'tp',
            airline: `${a.airline} + ${b.airline}`,
          });
        }
      }
    }
  }
}
combos.sort((x, y) => x.price - y.price);

// --- 3. Подвоз из Актау -------------------------------------------------------
// Второе плечо покупается из Алматы/Астаны, но сидим мы в Актау, поэтому честная
// цифра для сравнения городов — второе плечо ПЛЮС подвоз.
const feeder = {};
for (const o of ORIGINS) {
  const f = cheapest(offers.filter(x => x.from === FEEDER && x.to === o));
  if (f) feeder[o] = f;
}

// --- 4. Архив цен -------------------------------------------------------------
// Формат сверен с живым ответом: data — массив записей с value и depart_date,
// return_date пустой = one-way. Приоритет датам нашего окна, иначе выборка шире.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inWindow(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;
    if (!Array.isArray(data)) continue;
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;
      pushHist(`${t.origin}-${t.destination}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = { min: s[0], median: s[Math.floor(s.length / 2)], count: s.length,
                 scope: useWin ? 'наши даты' : 'все даты' };
}

// --- 5. Сводка по парам «откуда × куда» ---------------------------------------
const routes = {};
for (const origin of ORIGINS) {
  for (const dst of VN) {
    const key = `${origin}-${dst}`;
    const through = offers.filter(o => o.from === origin && o.to === dst);
    const self = combos.filter(c => c.origin === origin && c.to === dst);
    if (!through.length && !self.length) continue;

    const byDate = {};
    for (const o of through) {
      if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
    }
    const best = cheapest(through);
    const bestSelf = self[0] || null;
    const cheapestPrice = Math.min(best ? best.price : Infinity, bestSelf ? bestSelf.price : Infinity);
    const f = feeder[origin];

    routes[key] = {
      origin, dst, label: `${name(origin)} → ${name(dst)}`,
      through: { best, byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)), count: through.length },
      self: { best: bestSelf, top: self.slice(0, 3), count: self.length },
      feeder: f || null,
      // полная стоимость из Актау: лучшее второе плечо + подвоз
      total: (f && Number.isFinite(cheapestPrice)) ? cheapestPrice + f.price : null,
    };
  }
}

const all = [];
for (const [key, r] of Object.entries(routes)) {
  if (r.through.best) all.push({ ...r.through.best, key, label: r.label, mode: 'through' });
  if (r.self.best) all.push({ ...r.self.best, key, label: r.label, mode: 'self' });
}
all.sort((a, b) => a.price - b.price);

return [{ json: {
  window: WINDOW, origins: ORIGINS, hubs: HUBS, feeder_from: FEEDER,
  routes, best: all[0] || null, feeder, stats,
  count: offers.length, comboCount: combos.length,
} }];

// ===================== НАСТРОЙКИ =====================
const THRESHOLD = 25000;       // 🔥 порог по сквозному билету Казахстан → Вьетнам, ₽
const SELF_THRESHOLD = 23000;  // 🔥 порог для связки из двух билетов через хаб
const DROP_PCT = 12;           // 📉 мягкий алерт: падение от прошлого минимума, %
const CHAT_ID = '648226895';
// Откалибровано по данным 18.08.2026 (сквозные из Алматы/Астаны, октябрь):
//   Астана → Хошимин 25 561 ₽, Алматы → Нячанг 25 765 ₽, Алматы → Хошимин 25 984 ₽.
//   Для сравнения из Актау было 36–37 тыс. одним билетом — вылет из ALA/NQZ дешевле на ~10 тыс.
// SELF_THRESHOLD пока навскидку: связки через хаб из ALA/NQZ живьём ещё не считались
// (в старых данных не было запросов ALA→хаб), пересчитать после первого полного прогона.
// =====================================================

const agg = $('Aggregate').first().json;
const store = $getWorkflowStaticData('global');

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}` : '';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline}` +
  (stops(o) ? ` · ${stops(o)}` : '');

// транзит без визы: Дубай/Шарджа/Стамбул/Ташкент/Бангкок/КЛ — ок, Китай отдельно
const VISA = {
  URC: '\n⚠️ Транзит через Китай — нужен транзитный безвиз, проверь условия под свой паспорт.',
};

const verdict = (key, price) => {
  const s = (agg.stats || {})[key];
  if (!s || !s.median || !s.count) return '';
  const pct = Math.round((price / s.median) * 100);
  const where = s.scope === 'наши даты' ? 'дату окна' : 'дату в архиве';
  return `\n📊 ${pct} % от цены на типичную ${where} ` +
         `(медиана по датам ${rub(s.median)}, самая дешёвая ${rub(s.min)}, дат: ${s.count})`;
};

// подвоз из Актау — второе плечо покупается из Алматы/Астаны, но летим мы туда из Актау
const withFeeder = r => {
  if (!r.feeder) return '';
  return `\n🚌 + подвоз ${describe(r.feeder)} из ${agg.feeder_from}` +
         (r.total ? `, итого ~${rub(r.total)}` : '');
};

const out = [];
const push = text => out.push({ json: { chat_id: CHAT_ID, text } });

for (const [key, r] of Object.entries(agg.routes || {})) {
  // ---------- одним билетом ----------
  const t = r.through.best;
  if (t) {
    const k = `through:${key}`;
    const last = (store[k] == null) ? null : Number(store[k]);
    const was = (last == null) ? '' : ` (было ${rub(last)})`;

    let head = null;
    if (t.price <= THRESHOLD && (last == null || t.price < last)) head = `🔥 ${r.label}`;
    else if (last != null && t.price <= last * (1 - DROP_PCT / 100)) head = `📉 ${r.label}: цена упала`;
    store[k] = t.price;

    if (head) {
      let text = `${head}\n${describe(t)}${was}` + verdict(key, t.price) + withFeeder(r);
      if (head.startsWith('🔥')) text += '\nБери, пока не разобрали!';
      text += '\n⚠️ Цена из кэша Aviasales — проверь на сайте перевозчика.';
      push(text);
    }
  }

  // ---------- двумя билетами через хаб ----------
  const s = r.self.best;
  if (s) {
    const k = `self:${key}`;
    const last = (store[k] == null) ? null : Number(store[k]);
    const was = (last == null) ? '' : ` (было ${rub(last)})`;

    let head = null;
    if (s.price <= SELF_THRESHOLD && (last == null || s.price < last)) head = `🔥 ${r.label} через ${s.hub_city}`;
    else if (last != null && s.price <= last * (1 - DROP_PCT / 100)) head = `📉 ${r.label} через ${s.hub_city}: дешевле`;
    store[k] = s.price;

    if (head) {
      const cheaper = r.through.best ? r.through.best.price - s.price : null;
      push(`${head}\n${rub(s.price)} — две отдельные брони${was}` +
        (cheaper && cheaper > 0 ? `, на ${rub(cheaper)} дешевле одного билета` : '') + `\n` +
        `  1) ${describe(s.legA)}\n` +
        `  2) ${describe(s.legB)}\n` +
        `  стыковка ${s.layover_h} ч, ${s.hub_city}` +
        (s.layover_h > 10 ? ' — нужна ночёвка, считай отель в стоимость' : '') +
        withFeeder(r) +
        `\n⚠️ Билеты разные: опоздание на второй никто не компенсирует. ` +
        `Багаж получать и сдавать заново, время стыковки проверить руками.` +
        (VISA[s.hub] || ''));
    }
  }
}

return out;

// Запросы в Travelpayouts под второе плечо: Казахстан -> Вьетнам, октябрь 2026.
// Вылет из Алматы или Астаны (решение 18.08.2026): оттуда рейсов кратно больше,
// чем из Актау, и второе плечо покупается как отдельный билет.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами, не аэропортовыми. Проверено 18.08.2026:
// спрашиваешь CXR — приходит NHA (Нячанг), GYD — приходит BAK, а на DXB вдобавок
// прилетают рейсы через SHJ (Шарджа). В списках держим то, что API ОТДАЁТ.
const MONTH = '2026-10';
const ORIGINS = ['ALA', 'NQZ'];          // откуда реально летим во Вьетнам
const VN = ['SGN', 'NHA'];               // Хошимин и Нячанг
const HUBS = ['DXB', 'SHJ', 'IST', 'TAS', 'BKK', 'KUL', 'URC'];
const FEEDER = 'SCO';                    // Актау -> Алматы/Астана, подвоз к плечу

const out = [];
// 1. сквозные: то, что рынок продаёт одним билетом
for (const o of ORIGINS) for (const d of VN) out.push({ json: { origin: o, destination: d, leg: 'through', month: MONTH } });
// 2. подвоз из Актау — чтобы считать полную стоимость, а не только второе плечо
for (const o of ORIGINS) out.push({ json: { origin: FEEDER, destination: o, leg: 'feeder', month: MONTH } });
// 3. половинки связок через хаб
for (const o of ORIGINS) for (const h of HUBS) out.push({ json: { origin: o, destination: h, leg: 'legA', month: MONTH } });
for (const h of HUBS) for (const d of VN) out.push({ json: { origin: h, destination: d, leg: 'legB', month: MONTH } });
return out;

// Архив цен Travelpayouts по второму плечу — «дёшево сейчас или нет».
// Только сквозные маршруты: медиану по связке из двух билетов никто не считает,
// сравнивать будет не с чем.
// Эндпоинт один — /v2/prices/latest; /v1/prices/calendar выкинут (отдаёт цены
// туда-обратно и игнорирует запрошенный месяц), подробности в плече 1.
const YEAR_START = '2026-01-01';
const ROUTES = [['ALA', 'SGN'], ['ALA', 'NHA'], ['NQZ', 'SGN'], ['NQZ', 'NHA']];

const out = [];
for (const [origin, destination] of ROUTES) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Плечо 2: Казахстан -> Вьетнам, октябрь 2026 =====
// Вылет из Алматы (ALA) или Астаны (NQZ) — из Актау рейсов во Вьетнам почти нет,
// а из этих двух городов рынок нормальный. Считаем три вещи на каждый маршрут:
//   through — один билет, как продаёт рынок;
//   self    — два отдельных билета через хаб (часто дешевле, но риск стыковки на нас);
//   total   — то же плюс подвоз Актау -> Алматы/Астана, чтобы видеть полную стоимость.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами (CXR->NHA, GYD->BAK, на DXB прилетает
// ещё и SHJ). В списках держим то, что API ОТДАЁТ, иначе фильтр съедает всю выдачу.
const SUF = ' Cmd'; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-10-01', max: '2026-10-31' };
const ORIGINS = ['ALA', 'NQZ'];
const VN = ['SGN', 'NHA'];
const HUBS = ['DXB', 'SHJ', 'IST', 'TAS', 'BKK', 'KUL', 'URC'];
const FEEDER = 'SCO';
const ASSUMED_LEG_H = 4;
const MIN_LAYOVER_H = 6;    // международная стыковка: багаж, паспортный контроль
const MAX_LAYOVER_H = 36;   // дольше — это уже вторая поездка, а не стыковка

// Расширено по факту выдачи 18.08.2026. Коды FS, C6, HH, 3L не расшифрованы —
// покажутся как есть, это честнее выдуманного названия.
const AIRLINES = {
  FZ: 'flydubai', EK: 'Emirates', TK: 'Turkish', VF: 'AJet', HY: 'Uzbekistan',
  KC: 'Air Astana', DV: 'SCAT', J2: 'AZAL', VJ: 'VietJet', VN: 'Vietnam Airlines',
  QH: 'Bamboo', CZ: 'China Southern', SU: 'Аэрофлот', U6: 'Уральские', QR: 'Qatar',
  G9: 'Air Arabia', IX: 'Air India Express', AI: 'Air India', GF: 'Gulf Air',
  PC: 'Pegasus', D7: 'AirAsia X', XJ: 'Thai AirAsia X', CA: 'Air China',
  MU: 'China Eastern', XY: 'flynas', KU: 'Kuwait Airways', WY: 'Oman Air',
  '6E': 'IndiGo', OD: 'Batik Air', ZE: 'Eastar Jet', IQ: 'Qazaq Air', TG: 'Thai Airways',
  MH: 'Malaysia Airlines', AK: 'AirAsia', SQ: 'Singapore', BI: 'Royal Brunei',
};
const CITY = {
  SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', SGN: 'Хошимин', NHA: 'Нячанг',
  DXB: 'Дубай', SHJ: 'Шарджа', IST: 'Стамбул', TAS: 'Ташкент',
  BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи',
};
const name = c => CITY[c] || c;

const inWindow = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const hours = ms => ms / 3600000;

// --- 1. Разбор ответов Travelpayouts -----------------------------------------
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inWindow(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: t.origin, to: t.destination, date, depart_at, price,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        link: t.link || null,
      });
    }
  }
} catch (e) {}

const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
const minByDate = (from, to) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  return Object.values(byDate);
};
const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

// --- 2. Связки через хаб ------------------------------------------------------
// Стыковку проверяем по времени вылета и прилёта, а не по датам: иначе получаются
// схемы, где второй рейс улетает раньше, чем приземлился первый.
const combos = [];
for (const origin of ORIGINS) {
  for (const hub of HUBS) {
    const legA = minByDate(origin, hub);
    if (!legA.length) continue;
    for (const dst of VN) {
      const legB = minByDate(hub, dst);
      if (!legB.length) continue;
      for (const a of legA) {
        const arr = arrivalOf(a);
        if (!arr) continue;
        for (const b of legB) {
          const dep = new Date(b.depart_at);
          if (isNaN(dep)) continue;
          const gap = hours(dep - arr);
          if (gap < MIN_LAYOVER_H || gap > MAX_LAYOVER_H) continue;
          combos.push({
            origin, to: dst, hub, hub_city: name(hub),
            price: a.price + b.price, date: a.date,
            layover_h: Math.round(gap * 10) / 10,
            legA: a, legB: b, kind: 'self', src: 'tp',
            airline: `${a.airline} + ${b.airline}`,
          });
        }
      }
    }
  }
}
combos.sort((x, y) => x.price - y.price);

// --- 3. Подвоз из Актау -------------------------------------------------------
// Второе плечо покупается из Алматы/Астаны, но сидим мы в Актау, поэтому честная
// цифра для сравнения городов — второе плечо ПЛЮС подвоз.
const feeder = {};
for (const o of ORIGINS) {
  const f = cheapest(offers.filter(x => x.from === FEEDER && x.to === o));
  if (f) feeder[o] = f;
}

// --- 4. Архив цен -------------------------------------------------------------
// Формат сверен с живым ответом: data — массив записей с value и depart_date,
// return_date пустой = one-way. Приоритет датам нашего окна, иначе выборка шире.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inWindow(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;
    if (!Array.isArray(data)) continue;
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;
      pushHist(`${t.origin}-${t.destination}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = { min: s[0], median: s[Math.floor(s.length / 2)], count: s.length,
                 scope: useWin ? 'наши даты' : 'все даты' };
}

// --- 5. Сводка по парам «откуда × куда» ---------------------------------------
const routes = {};
for (const origin of ORIGINS) {
  for (const dst of VN) {
    const key = `${origin}-${dst}`;
    const through = offers.filter(o => o.from === origin && o.to === dst);
    const self = combos.filter(c => c.origin === origin && c.to === dst);
    if (!through.length && !self.length) continue;

    const byDate = {};
    for (const o of through) {
      if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
    }
    const best = cheapest(through);
    const bestSelf = self[0] || null;
    const cheapestPrice = Math.min(best ? best.price : Infinity, bestSelf ? bestSelf.price : Infinity);
    const f = feeder[origin];

    routes[key] = {
      origin, dst, label: `${name(origin)} → ${name(dst)}`,
      through: { best, byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)), count: through.length },
      self: { best: bestSelf, top: self.slice(0, 3), count: self.length },
      feeder: f || null,
      // полная стоимость из Актау: лучшее второе плечо + подвоз
      total: (f && Number.isFinite(cheapestPrice)) ? cheapestPrice + f.price : null,
    };
  }
}

const all = [];
for (const [key, r] of Object.entries(routes)) {
  if (r.through.best) all.push({ ...r.through.best, key, label: r.label, mode: 'through' });
  if (r.self.best) all.push({ ...r.self.best, key, label: r.label, mode: 'self' });
}
all.sort((a, b) => a.price - b.price);

return [{ json: {
  window: WINDOW, origins: ORIGINS, hubs: HUBS, feeder_from: FEEDER,
  routes, best: all[0] || null, feeder, stats,
  count: offers.length, comboCount: combos.length,
} }];

// Ответ на /prices по второму плечу: Казахстан -> Вьетнам.
const a = $('Aggregate Cmd').first().json;
const chat_id = $('On Command').first().json.message.chat.id;

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}` : '';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline}` +
  (stops(o) ? ` · ${stops(o)}` : '');

let text = `✈️ Казахстан → Вьетнам, ${dm(a.window.min)} – ${dm(a.window.max)}\n`;
if (a.best) {
  text += `Дешевле всего: ${rub(a.best.price)} — ${a.best.label}` +
          (a.best.mode === 'self' ? ` (двумя билетами через ${a.best.hub_city})` : ' (одним билетом)') + `\n`;
}
text += `\n`;

// сортируем по лучшей доступной цене: сверху то, куда реально дешевле
const best = r => Math.min(
  r.through.best ? r.through.best.price : Infinity,
  r.self.best ? r.self.best.price : Infinity);
const entries = Object.entries(a.routes || {}).sort((x, y) => best(x[1]) - best(y[1]));

for (const [key, r] of entries) {
  text += `${r.label}\n`;
  text += `  Одним билетом: ${r.through.best ? describe(r.through.best) : 'нет вариантов'}\n`;
  const s = (a.stats || {})[key];
  if (r.through.best && s && s.median) {
    text += `    ${Math.round((r.through.best.price / s.median) * 100)} % от цены на типичную дату ` +
            `(медиана по датам ${rub(s.median)}, самая дешёвая ${rub(s.min)}, дат: ${s.count})\n`;
  }
  if (r.self.best) {
    text += `  Двумя билетами:\n`;
    for (const c of r.self.top) {
      text += `    • ${rub(c.price)} через ${c.hub_city}: ${describe(c.legA)} + ${describe(c.legB)}, ` +
              `стыковка ${c.layover_h} ч\n`;
    }
  }
  if (r.feeder) {
    text += `  Подвоз из ${a.feeder_from}: ${describe(r.feeder)}` +
            (r.total ? ` → итого ~${rub(r.total)}` : '') + `\n`;
  }
  text += `\n`;
}

text += `Связок посчитано: ${a.comboCount}, офферов всего: ${a.count}.\n` +
        `Хабы: ${(a.hubs || []).join(', ')}.\n` +
        `«Итого» — второе плечо плюс перелёт из Актау, даты между собой не сведены.\n` +
        `⚠️ «Двумя билетами» — две отдельные брони, стыковка на твой риск. ` +
        `Цены из кэша Aviasales, до 48 ч давности.`;

return [{ json: { chat_id, text } }];

// Уведомление о падении воркфлоу. Троттлинг на ноду — 30 мин:
// без него лежащий внешний API заваливает чат десятками одинаковых сообщений.
const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ FlightWatch VN упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];
